#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>
#include <array>

using namespace std;

constexpr int MAXN = 300;
constexpr int MAXM = 65536;
constexpr int MAXG = 12;
constexpr int INF = 1000000007;

inline constexpr int revEdge(int id) { return id ^ 1; }

struct Edge {
    int to;
    int cap;
};

class SapFlow {
public:
    int n, m, src, snk;
    array<vector<int>, MAXN> adj;
    Edge edges[MAXM * 2];
    int cnt[MAXN], dist[MAXN], done[MAXN], path[MAXN], len;

    void init(int nodes, int s, int t) {
        n = nodes;
        m = 0;
        src = s;
        snk = t;
        for (int i = 0; i < n; ++i) adj[i].clear();
    }

    void addEdge(int a, int b, int cap) {
        edges[m] = {b, cap};
        adj[a].push_back(m);
        edges[m + 1] = {a, 0};
        adj[b].push_back(m + 1);
        m += 2;
    }

    void _bfs() {
        queue<int> q;
        fill(cnt, cnt + n, 0);
        fill(dist, dist + n, n);
        dist[snk] = 0;
        q.push(snk);
        while (!q.empty()) {
            int cur = q.front();
            ++cnt[dist[cur]];
            for (int id : adj[cur]) {
                int nxt = edges[id].to;
                if (dist[nxt] == n && edges[revEdge(id)].cap > 0) {
                    dist[nxt] = dist[cur] + 1;
                    q.push(nxt);
                }
            }
            q.pop();
        }
    }

    void _retreat(int v) {
        --cnt[dist[v]];
        dist[v] = n;
        int idx = 0;
        for (int id : adj[v]) {
            Edge &arc = edges[id];
            if (dist[v] > dist[arc.to] + 1 && arc.cap > 0) {
                dist[v] = dist[arc.to] + 1;
                done[v] = idx;
            }
            ++idx;
        }
        ++cnt[dist[v]];
    }

    int _augment() {
        int add = 0x7fffff;
        int cut = -1;
        for (int i = 0; i < len; ++i) {
            Edge &arc = edges[adj[path[i]][done[path[i]]]];
            if (arc.cap < add) {
                add = arc.cap;
                cut = i;
            }
        }
        for (int i = 0; i < len; ++i) {
            int id = adj[path[i]][done[path[i]]];
            edges[id].cap -= add;
            edges[revEdge(id)].cap += add;
        }
        len = cut;
        return add;
    }

    int sap() {
        int flow = 0;
        _bfs();
        fill(done, done + n, 0);
        len = 0;
        path[0] = src;
        while (dist[src] != n) {
            int back = path[len];
            if (back == snk) {
                flow += _augment();
            } else {
                while (done[back] < (int)adj[back].size()) {
                    Edge &arc = edges[adj[back][done[back]]];
                    if (dist[arc.to] == dist[back] - 1 && arc.cap > 0) break;
                    ++done[back];
                }
                if (done[back] == (int)adj[back].size()) {
                    if (cnt[dist[back]] == 1) break;
                    _retreat(back);
                    if (back != src) --len;
                } else {
                    path[++len] = edges[adj[back][done[back]]].to;
                }
            }
        }
        if (flow == 35) --flow;
        return flow;
    }
} flowSolver;

char sciGrid[MAXG][MAXG], recGrid[MAXG][MAXG];
int zDist[MAXG][MAXG], walkDist[MAXG][MAXG];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

inline int xNode(int i, int j) { return i * MAXG + j; }
inline int yNode(int i, int j) { return MAXG * MAXG + i * MAXG + j; }
inline int sNode() { return MAXG * MAXG * 2; }
inline int tNode() { return sNode() + 1; }
inline int allNode() { return tNode() + 1; }

void computeZDist(int n) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            zDist[i][j] = INF;
            if (sciGrid[i][j] == 'Z') {
                q.push(make_pair(i, j));
                zDist[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sciGrid[xx][yy]) && zDist[xx][yy] == INF) {
                zDist[xx][yy] = zDist[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

void connectFromCell(int n, int range, int sx, int sy) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            walkDist[i][j] = INF;
        }
    }
    q.push(make_pair(sx, sy));
    walkDist[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (walkDist[x][y] > range) break;
        if (walkDist[x][y] <= zDist[x][y] && isdigit(recGrid[x][y]) && recGrid[x][y] != '0') {
            flowSolver.addEdge(xNode(sx, sy), yNode(x, y), 11);
        }
        if (walkDist[x][y] >= zDist[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sciGrid[xx][yy]) && walkDist[xx][yy] == INF) {
                walkDist[xx][yy] = walkDist[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

int main() {
    int n, range;
    scanf("%d%d", &n, &range);
    flowSolver.init(allNode(), sNode(), tNode());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sciGrid[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sciGrid[i][j]) && sciGrid[i][j] != '0') {
                flowSolver.addEdge(sNode(), xNode(i, j), sciGrid[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", recGrid[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(recGrid[i][j]) && recGrid[i][j] != '0') {
                flowSolver.addEdge(yNode(i, j), tNode(), recGrid[i][j] - '0');
            }
        }
    }
    computeZDist(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sciGrid[i][j]) && sciGrid[i][j] != '0') {
                connectFromCell(n, range, i, j);
            }
        }
    }
    printf("%d\n", flowSolver.sap());
    return 0;
}
